// Exact projection documented in the SVG's own <metadata> block, so points we add
// line up with the county geometry: Equirectangular, standard parallel 46N,
// Natural Earth 1:10m admin boundaries.
export const HARTA_PROJECTION = {
	offsetX: 189.21353233183618,
	offsetY: 120.0,
	scale: 185.9547109463753,
	cosStandardParallel: 0.6946583704589973,
	minProjectedX: 14.061848522645022,
	minProjectedY: -48.274832,
};

export function projectLonLat(lon, lat) {
	const { offsetX, offsetY, scale, cosStandardParallel, minProjectedX, minProjectedY } = HARTA_PROJECTION;
	const x = offsetX + scale * (lon * cosStandardParallel - minProjectedX);
	const y = offsetY + scale * (-lat - minProjectedY);
	return [x, y];
}
